head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getOverflowX]<br/>GridView 컴포넌트의 overflowX 속성값을 반환합니다.",
    "validation" : [
        "auto 설정 시, getOverflowX() 는 overflowX 속성값을 'auto' 로 반환합니다.",
        "hidden 설정 시, getOverflowX() 는 overflowX 속성값을 'hidden' 으로 반환합니다.",
        "scroll 설정 시, getOverflowX() 는 overflowX 속성값을 'scroll' 로 반환합니다.",
        "미설정 시, getOverflowX() 는 기본 overflowX 속성값을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 - con_overflowX 값을 overflowX 속성으로 적용
    let properties = {
        overflowX: con_overflowX.getValue(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (4 Column)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 테스트 참고 라벨 (검증 운영 정보) — grid 생성 전에 먼저 생성
    $c.gcm.createLabel('label="[전제] con(overflowX) 값을 선택하고 (Target 재생성) 으로 그리드 생성 (컬럼 폭 합 > 그리드 폭 => 가로 넘침 상태)\n[절차] (getOverflowX) 클릭\n[확인] 반환값이 선택한 overflowX 값(auto/hidden/scroll), 미설정 시 기본값과 일치"', '', 'label1');

    // target 생성 (가로 스크롤이 나도록 컬럼 폭 합 > 그리드 폭)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:250px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getOverflowX : 현재 그리드의 overflowX 속성값 반환 (메인 검증)
scwin.btn_getOverflowX_onclick = function () {
    let rtn = target1.getOverflowX();
    wf_body_bottom.getObj("scwin").setReturnValue("getOverflowX : " + rtn);
};
